"""The must-know Reading & Writing rules. Every question is tied to exactly one rule.

These are ordered by how many points they're worth to a student already near 700:
the Standard English Conventions rules are pure pattern recognition (learn once,
score every time), followed by the Expression of Ideas strategies, then the
reading strategies.
"""

RULES = [
    # ------------------------------------------------------------------ Boundaries
    dict(id="clauses", group="Punctuation (Boundaries)", title="Joining two complete sentences",
         rule="Two independent clauses (each could stand alone as a sentence) can be joined only by a <b>period</b>, a <b>semicolon</b>, a <b>comma + FANBOYS</b> (for, and, nor, but, or, yet, so), or a <b>colon</b> when the second explains the first. A comma alone is a <b>comma splice</b>, and that choice is always wrong.",
         example="Monarchs migrate south each fall<b>;</b> no single butterfly makes the round trip.",
         trap="Choices that look &ldquo;lighter&rdquo; (just a comma, or nothing) are tempting. <b>Test:</b> cover the punctuation. If both sides are full sentences, only . ; : or , + FANBOYS works.",
         freq="Very common"),
    dict(id="colon", group="Punctuation (Boundaries)", title="Colons",
         rule="A colon must come after a <b>complete sentence</b>, and it introduces something that explains or lists: an explanation, an example, or a list. What follows can be a fragment.",
         example="The team identified three factors<b>:</b> temperature, fish abundance, and distance from shore.",
         trap="Never put a colon after <i>such as</i>, <i>including</i>, <i>are</i>, or a verb, because the words before it aren't a complete sentence (&ldquo;artists such as<b>:</b> Kahlo&rdquo; is wrong).",
         freq="Common"),
    dict(id="nonessential", group="Punctuation (Boundaries)", title="Extra information: match the pair",
         rule="Extra (nonessential) information is set off by a <b>matching pair</b>: two commas, two dashes, or two parentheses. Look at how the extra phrase <b>opens</b>, and close it with the same mark.",
         example="The axolotl<b>&mdash;</b>a salamander native to Mexico City<b>&mdash;</b>can regrow limbs.",
         trap="<b>Essential</b> information takes no commas at all. In &ldquo;Achebe's novel <i>Things Fall Apart</i>,&rdquo; the title is essential because Achebe wrote several novels; commas would wrongly imply he wrote only one.",
         freq="Very common"),
    dict(id="nopunct", group="Punctuation (Boundaries)", title="Don't punctuate the core",
         rule="No single punctuation mark goes between a <b>subject and its verb</b>, a <b>verb and its object</b>, a <b>preposition and its object</b>, or before a <b>that</b>-clause. When in doubt, the version with no punctuation is often right.",
         example="The study's most surprising finding was that older trees absorbed more carbon. (no comma after <i>was</i> or <i>that</i>)",
         trap="A long subject tempts you to &ldquo;breathe&rdquo; with a comma before the verb. Don't: &ldquo;The letters she exchanged with her editor over three decades<b>,</b> provide&hellip;&rdquo; is wrong.",
         freq="Very common"),
    dict(id="however", group="Punctuation (Boundaries)", title="However, therefore & lists with commas",
         rule="Words like <i>however, therefore, moreover, consequently, thus</i> are not conjunctions, so they can't join two sentences with just commas. Use <b>; however,</b> or <b>. However,</b>. Also, when list items already contain commas, separate the items with <b>semicolons</b>.",
         example="The supports had rotted<b>; therefore,</b> engineers replaced them.",
         trap="&ldquo;, however,&rdquo; between two complete sentences is a comma splice in disguise.",
         freq="Common"),
    dict(id="possessive", group="Punctuation (Boundaries)", title="Possessives & its/it's",
         rule="<b>its</b> = belonging to it, <b>it's</b> = it is; <b>their</b> = belonging to them, <b>they're</b> = they are. Singular possessive: <b>condor's</b>. Plural possessive: <b>teams'</b>. Plain plural, no apostrophe: <b>teams</b>.",
         example="The Andean <b>condor's</b> wings allow <b>it</b> to soar.",
         trap="Use the rest of the sentence to decide singular or plural: &ldquo;allow <i>it</i>&rdquo; means one condor; &ldquo;<i>Both</i> research teams&rsquo;&rdquo; means plural.",
         freq="Common"),
    # ------------------------------------------------------------------ Form, Structure, and Sense
    dict(id="agreement", group="Grammar (Form, Structure, and Sense)", title="Subject–verb agreement",
         rule="Find the <b>real subject</b>: cross out prepositional phrases (<i>of the manuscripts</i>) and extra information between commas. <i>Each, every, one of, either, neither</i> are singular. A collection or group noun is singular. In <i>neither&hellip;nor</i>, the verb matches the nearer subject.",
         example="The <b>collection</b> of ancient manuscripts, many of which were rescued from floods, <b>is</b> housed in an archive.",
         trap="The noun right before the blank is usually <i>not</i> the subject. The SAT puts a plural noun there on purpose. Also watch inverted sentences: &ldquo;Near the center <b>lies</b> a black hole.&rdquo;",
         freq="Very common"),
    dict(id="pronoun", group="Grammar (Form, Structure, and Sense)", title="Pronoun agreement & clarity",
         rule="A pronoun must match its noun in number: a company, team, or species is <b>it/its</b>, and plural nouns are <b>they/their</b>. If <i>they</i> or <i>it</i> could refer to two different things, choose the specific noun.",
         example="When the company released <b>its</b> first electric truck, &hellip;",
         trap="People often say &ldquo;the company&hellip; <i>their</i>.&rdquo; The SAT always wants <b>its</b> for a single organization.",
         freq="Common"),
    dict(id="tense", group="Grammar (Form, Structure, and Sense)", title="Verb tense: follow the timeline",
         rule="Match the tense to the clues in the passage: dates and the other verbs. Use <b>has/have + verb</b> for something that started in the past and continues (&ldquo;<i>Since</i> 1990, Hubble <b>has made</b>&hellip;&rdquo;) and <b>had + verb</b> for something that happened before another past event.",
         example="Fleming noticed that the mold <b>had killed</b> the bacteria.",
         trap="Don't pick a tense because it &ldquo;sounds formal.&rdquo; Underline the time words (<i>since, before, in 1928</i>) and let them decide.",
         freq="Common"),
    dict(id="modifier", group="Grammar (Form, Structure, and Sense)", title="Dangling modifiers",
         rule="An introductory phrase (&ldquo;Born in 1907,&rdquo; &ldquo;After analyzing the data,&rdquo;) must be followed <b>immediately</b> by the person or thing that did it or is described by it.",
         example="After analyzing thousands of recordings, <b>the researchers</b> concluded&hellip;",
         trap="Ask &ldquo;<i>who</i> was born in 1907?&rdquo; The answer must be the first noun after the comma, not &ldquo;her paintings&rdquo; or &ldquo;the conclusion.&rdquo;",
         freq="Common"),
    dict(id="verbform", group="Grammar (Form, Structure, and Sense)", title="Complete sentences & parallel forms",
         rule="Every sentence needs a <b>main verb</b>. An <i>-ing</i> word or a <i>to</i>-verb alone can't be one. A comma followed by an <i>-ing</i> phrase is often correct when it describes the result of the main clause. Items in a list must have the <b>same form</b> (to monitor, to remove, and to educate).",
         example="The coelacanth, a fish once thought extinct, <b>was</b> rediscovered in 1938.",
         trap="After a long interruption between commas, check that the subject still gets a real verb: &ldquo;The coelacanth, &hellip;, <i>being</i> rediscovered&rdquo; is a fragment.",
         freq="Common"),
    # ------------------------------------------------------------------ Expression of Ideas
    dict(id="transitions", group="Expression of Ideas", title="Transitions: name the relationship first",
         rule="<b>Before looking at the choices</b>, cover them and label how the new sentence relates to the one before it: <b>contrast</b> (however), <b>example</b> (for example), <b>cause/result</b> (therefore, as a result), <b>addition</b> (moreover), <b>similarity</b> (similarly), <b>restatement</b> (in other words), <b>concession</b> (still, nonetheless), <b>sequence</b> (next, then).",
         example="Many desert plants store water. <b>For example,</b> the saguaro can hold 200 gallons.",
         trap="Two choices from the same category (<i>however / nevertheless</i>) usually mean neither is right. And <i>similarly</i> needs a true parallel, not just &ldquo;one more fact.&rdquo;",
         freq="Very common"),
    dict(id="synthesis", group="Expression of Ideas", title="Notes questions: the goal is everything",
         rule="For &ldquo;student's notes&rdquo; questions, <b>read the goal in the question first</b> and skip the notes. Then pick the choice that does exactly what the goal says: emphasize a <i>difference</i>, introduce something to an <i>unfamiliar</i> audience (it must say what the thing is), present a <i>similarity</i>, explain a <i>cause</i>, and so on.",
         example="Goal: &ldquo;emphasize a difference in location.&rdquo; Answer: &ldquo;<b>Whereas</b> Hubble orbits Earth, Webb sits 1.5 million km away.&rdquo;",
         trap="Every choice is accurate, because they all come from the notes. Accuracy doesn't matter here; only the goal does. These should take about 30 seconds.",
         freq="Very common"),
    # ------------------------------------------------------------------ Craft and Structure
    dict(id="wordsincontext", group="Reading (Craft and Structure)", title="Words in context: predict, then match",
         rule="Cover the choices and fill the blank with <b>your own word</b> based on the clues (a colon, <i>but/although</i>, a definition later in the sentence). Then pick the choice closest to your word.",
         example="&ldquo;&hellip;her argument was ______: she said so plainly.&rdquo; Your word: <i>simple</i>. Answer: <b>straightforward</b>.",
         trap="The most common meaning of a word is often the trap (&ldquo;arresting&rdquo; meaning &ldquo;stopping&rdquo;). Watch whether the passage sets up a positive or negative tone, too.",
         freq="Very common"),
    dict(id="structure", group="Reading (Craft and Structure)", title="Purpose & structure: what does it DO?",
         rule="Describe the <b>job</b> a sentence or text does with a verb: <i>introduces, illustrates, qualifies, challenges, presents a consequence of</i>. The right answer is usually a fairly abstract description of the text's moves.",
         example="&ldquo;Common belief &rarr; true for some &rarr; but exceptions&rdquo; = presents a belief and then <b>qualifies</b> it.",
         trap="Choices that repeat words from the text but describe the wrong job, or that are too strong (&ldquo;refutes,&rdquo; &ldquo;proves&rdquo;) when the text only qualifies.",
         freq="Common"),
    dict(id="crosstext", group="Reading (Craft and Structure)", title="Two texts: how would author 2 respond?",
         rule="Write one line for each text's <b>main claim</b>. To answer &ldquo;how would Text 2's author respond to Text 1,&rdquo; base the answer on what Text 2 actually says, applied to Text 1's claim.",
         example="Text 1: higher wages &rarr; fewer jobs. Text 2: a study found no job losses. Response: <b>evidence that it didn't happen in at least one case</b>.",
         trap="Overstated responses (&ldquo;always,&rdquo; &ldquo;completely wrong&rdquo;) when Text 2 only offers a counterexample.",
         freq="Common"),
    # ------------------------------------------------------------------ Information and Ideas
    dict(id="evidence", group="Reading (Information and Ideas)", title="Evidence must match the whole claim",
         rule="For &ldquo;which quotation/finding would best support the claim,&rdquo; split the claim into its key parts and pick the choice that matches <b>every</b> part. For a hypothesis, choose the finding that would only happen if the hypothesis were true.",
         example="Claim: hope asks nothing of us, even in the most desperate times. The quotation needs both parts: &ldquo;asks nothing&rdquo; <i>and</i> &ldquo;desperate times.&rdquo;",
         trap="Choices that are on topic and true but support only half of the claim.",
         freq="Common"),
    dict(id="quant", group="Reading (Information and Ideas)", title="Tables & graphs: read the claim first",
         rule="Read the <b>claim in the passage</b> first, then the data. The right choice is accurate to the data <b>and</b> directly supports that specific claim.",
         example="Claim: bigger plots didn't always yield more. Answer: the <b>largest</b> plot yielded <b>less</b> than a smaller one.",
         trap="Choices that are 100% accurate about the table but irrelevant to the claim, and choices that misread a number.",
         freq="Common"),
    dict(id="inference", group="Reading (Information and Ideas)", title="Inferences: the most modest conclusion",
         rule="&ldquo;Most logically completes the text&rdquo; means the conclusion that <b>must</b> follow from the passage's evidence, and nothing more. Find the logical chain (A &rarr; B, so &hellip;) and finish it.",
         example="Bumblebees buzz-pollinate, honeybees can't, and buzz-pollinated tomatoes are larger &rarr; growers who want large tomatoes may benefit more from bumblebees.",
         trap="Extreme words (<i>all, never, prove, only</i>) and conclusions about things the passage never discussed.",
         freq="Common"),
    dict(id="mainidea", group="Reading (Information and Ideas)", title="Main idea: the whole text, not one detail",
         rule="The main idea covers the <b>whole</b> passage. Wrong answers are usually one true detail (too narrow) or something bigger than the text (too broad). In literary passages, watch for irony.",
         example="A paragraph that ends in a twist is about the twist.",
         trap="A choice that quotes the first sentence literally when the passage is ironic (as in <i>Pride and Prejudice</i>'s opening).",
         freq="Common"),
    # ------------------------------------------------------------------ strategy
    dict(id="pacing", group="Strategy", title="Pacing: bank time on grammar",
         rule="The R&W section gives about <b>71 seconds per question</b>. Grammar, transition, and notes questions should take 20&ndash;40 seconds each. That banks time for the reading-heavy questions earlier in the module. If a reading question passes 90 seconds, eliminate what you can, guess, mark it, and move on.",
         example="27 questions in 32 minutes: aim to reach the grammar questions with at least 14 minutes left.",
         trap="Re-reading a whole passage for a grammar question. You only need the sentence with the blank (and sometimes the one before it).",
         freq="Every module"),
]
